/* @lc app=leetcode id=3700 lang=kotlin */ class Solution { fun mm(a: Array<LongArray>, b: Array<LongArray>): Array<LongArray> = Array(a.size) { i -> LongArray(b.size) { j -> a.indices.fold(0L) { s, k -> (s + a[i][k] * b[k][j]) % 1_000_000_007L } } } fun ap(p: Array<LongArray>, x: LongArray): LongArray = LongArray(x.size) { i -> x.indices.fold(0L) { s, j -> (s + p[i][j] * x[j]) % 1_000_000_007L } } fun zigZagArrays(n: Int, l: Int, r: Int): Int = (r - l + 1).let { sz -> Array(2 * sz) { i -> LongArray(2 * sz) { j -> if (i < sz) (if (j >= sz && j - sz < i) 1L else 0L) else (if (j < sz && j > i - sz) 1L else 0L) } }.let { t -> generateSequence(Triple(t, n - 2, LongArray(2 * sz) { if (it < sz) it.toLong() else (2 * sz - 1 - it).toLong() })) { (p, ex, x) -> if (ex == 0) null else Triple(mm(p, p), ex shr 1, if (ex and 1 == 1) ap(p, x) else x) }.last().third.let { (it.sum() % 1_000_000_007L).toInt() } } } }